'use strict';
const assert=require('node:assert/strict');
const {create}=require('../demo-core');
let groups=0;const test=(name,fn)=>{fn();groups++;console.log('PASS '+name);};
const payload=(raw=.576,term=36)=>({source:'items_estimate',estimated_volume:raw,target_volume:Math.max(.5,raw),term_months:term,term_confirmed:true,items:[{id:'box',variant:'std',quantity:6}]});
test('manual capacity keeps two-decimal contract',()=>{const c=create();assert.throws(()=>c.setRequirement(.576,6,true),/INVALID_CAPACITY/);c.setRequirement(4.37,6,true);assert.equal(c.state().requirement.capacity_m3,4.37);});
test('item estimate preserves exact precision and raw value',()=>{const c=create();c.setEstimate(payload());assert.equal(c.state().requirement.capacity_m3,.576);assert.equal(c.state().requirement.estimated_volume,.576);assert.equal(c.state().requirement.term_months,36);});
test('minimum matching volume never overwrites raw estimate',()=>{const c=create();c.setEstimate(payload(.25));assert.equal(c.state().requirement.capacity_m3,.5);assert.equal(c.state().requirement.estimated_volume,.25);});
test('term edit keeps item estimate and invalidates prior quote',()=>{const c=create();c.setEstimate(payload());c.setTerm(7);assert.equal(c.state().requirement.capacity_m3,.576);assert.equal(c.state().requirement.estimated_volume,.576);assert.equal(c.state().requirement.term_months,7);assert.equal(c.state().quote,null);});
test('selection clearing preserves exact demand metadata',()=>{const c=create();c.setEstimate(payload());c.select(['SIM_BJ01_U01']);c.clearSelection();assert.equal(c.state().selected.length,0);assert.equal(c.state().requirement.estimated_volume,.576);});
test('matching excludes a unit below the exact estimate',()=>{const c=create();c.setEstimate(payload(.801));assert(!c.matchingUnits('SIM_BJ01').some(u=>u.volume===.8));});
test('exact item demand can quote and submit a coherent order',()=>{const c=create();c.setEstimate(payload());c.requestPhone();c.resolvePhone('success');c.select(['SIM_BJ01_U01']);c.setDate('2026-11-01');const q=c.quote(),o=c.submit();assert.equal(q.capacity_m3,.576);assert.equal(o.capacity_m3,.576);assert.equal(q.payable,o.payable);assert.equal(o.term_months,36);});
test('known capacity clears item provenance and rejects absent confirmation',()=>{const c=create();c.setEstimate(payload());c.setEstimate({source:'known_capacity_in_items_flow',target_volume:3.5,term_months:6,term_confirmed:true});assert.equal(c.state().requirement.estimated_volume,null);assert.deepEqual(c.state().requirement.items,[]);assert.throws(()=>c.setEstimate({source:'known_capacity_in_items_flow',target_volume:3.5,term_months:6,term_confirmed:false}),/SELECT_TERM/);});
test('malformed estimates and duplicate item ids are rejected',()=>{const c=create();for(const raw of [0,NaN,Infinity,201,.5761])assert.throws(()=>c.setEstimate(payload(raw)),/INVALID_ESTIMATE/);const p=payload();p.items.push({...p.items[0]});assert.throws(()=>c.setEstimate(p),/INVALID_ESTIMATE/);assert.throws(()=>c.setEstimate({...payload(),target_volume:.57}),/INVALID_ESTIMATE/);});
test('lease confirmation cannot be fabricated by an estimate payload',()=>{const c=create();assert.throws(()=>c.setEstimate({...payload(),term_months:null,term_confirmed:false}),/SELECT_TERM/);for(const term of [0,1.5,61])assert.throws(()=>c.setTerm(term),/INVALID_TERM/);});
console.log(JSON.stringify({groups,result:'PASS'}));
